-- Donjon : taux du composant par carte, boss sans apparition, pierres du dernier boss, panoplies.
SET @manque = (SELECT COUNT(*) = 0 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = 'acore_world' AND TABLE_NAME = 'solazeroth_v3_donjons_composants' AND COLUMN_NAME = 'taux');
SET @requete = IF(@manque, 'ALTER TABLE solazeroth_v3_donjons_composants ADD COLUMN taux TINYINT UNSIGNED NOT NULL DEFAULT 15', 'DO 0');
PREPARE requete FROM @requete;
EXECUTE requete;
DEALLOCATE PREPARE requete;
