-- Ebru : seuil des Cavernes ; le Disciple de Naralex : escorte en solo (v3_gouffre.cpp) ; Mocassins et
-- Ectoplasmes appelés sans SmartAI (leur script visait le disciple).
CREATE TABLE solazeroth_v3_t5_pnj_origine SELECT entry, npcflag, AIName, ScriptName FROM creature_template WHERE entry IN (5768, 3678, 5762, 5763);
DELETE FROM npc_text WHERE ID = 910002;
INSERT INTO npc_text (ID, text0_0, text0_1, Probability0) VALUES (910002, 'Les Cavernes des Lamentations sont sous nos pieds. Personne ne descend sans avoir prouvé qu''il connaît la savane.', 'Les Cavernes des Lamentations sont sous nos pieds. Personne ne descend sans avoir prouvé qu''il connaît la savane.', 1);
