INSERT INTO solazeroth_v3_donjons_seuils VALUES (43, 17, 6000, 910070, 5768, 910002, -163.49, 132.9, -73.66, 5.83, 'Descendre dans les Cavernes.', 'Falla Vent-de-sagesse doit d''abord t''envoyer, depuis le sommet de la colline.', 'Les Tarides ne parlent pas encore assez de toi : {pourcent} de la zone. Reviens à {seuil}.', 'Les Cavernes des Lamentations se passent par Ebru, dans la grotte des disciples, au-dessus de l''entrée. ');
