-- Objets qui lançaient une de ces quêtes : ils ne la lancent plus (l'Éclat luminescent sert à T35).
CREATE TABLE solazeroth_v3_t5_sans_quete SELECT i.entry, i.startquest FROM item_template i JOIN disables d ON d.sourceType = 1 AND d.entry = i.startquest AND d.comment = 'Sol''Azeroth v3 : quete d''origine des Cavernes' WHERE i.startquest > 0;
UPDATE item_template i JOIN solazeroth_v3_t5_sans_quete o ON o.entry = i.entry SET i.startquest = 0;
