-- Les quêtes T31 à T36.
INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredItemId1, RequiredItemCount1) VALUES (910071, 2, -1, 0, 718, 900, 0, 1, -797, -2037, 'Les peaux de déviants', 'Rapporte 10 Peaux de déviant à Nalpak, prises aux déviants de la grotte d''entrée.', 'Les bêtes d''en bas étaient des serpents, des lézards, des crocilisques. Le cauchemar les a tordues. Rapporte-moi dix de leurs peaux. Je veux comprendre ce qu''il leur fait. Et toi, tu apprendras à les tuer avant qu''elles ne te tuent.', 'Retourne voir Nalpak.', 910791, 1, 6443, 10);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910071, 910070, 0);
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910071, 1, 1, 'Les peaux ?');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910071, 1, 'Ces écailles poussent à l''envers… Prends cette cape. Elle est faite d''une peau saine, la dernière que j''ai trouvée.');
