INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredNpcOrGo1, RequiredNpcOrGoCount1, RequiredNpcOrGo2, RequiredNpcOrGoCount2, RequiredNpcOrGo3, RequiredNpcOrGoCount3, RequiredNpcOrGo4, RequiredNpcOrGoCount4) VALUES (910072, 2, -1, 0, 718, 930, 0, 1, -802, -2039, 'L''éradication des déviants', 'Dans les Cavernes, tue 5 Ravageurs, 5 Vipères, 5 Traînards et 5 Crocs-d''effroi déviants.', 'Les pires bêtes du cauchemar gardent les galeries. Les ravageurs, les vipères, les traînards, les crocs-d''effroi. Tant qu''elles grouillent, le disciple ne pourra pas avancer. Fais-en le ménage.', 'Retourne voir Ebru.', 37711, 10, 3636, 5, 5755, 5, 5761, 5, 5056, 5);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910072, 910070, 0);
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910072, 1, 1, 'Les déviants grouillent encore ?');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910072, 1, 'Moins nombreux. Le disciple respire mieux, je le sens d''ici. Prends ces Marques.');
