INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredItemId1, RequiredItemCount1) VALUES (910073, 2, -1, 0, 718, 930, 0, 1, -425, -2590, 'Fleur de serpent', 'Rapporte 8 Fleurs de serpent des Cavernes à l''apothicaire Helbrim.', 'Les spores que tu m''as rapportées viennent d''une fleur qui ne pousse que dans les Cavernes : la fleur de serpent. Avec elle, je peux faire un remède pour les gazelles, et peut-être pour la savane. Rapporte-m''en huit. Elles poussent près de l''eau, là où les déviants sont les plus nombreux.', 'Retourne voir Apothicaire Helbrim.', 910792, 1, 5339, 8);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910073, 910070, 0);
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910073, 1, 1, 'Les fleurs ?');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910073, 1, 'Huit fleurs. Les gazelles de la Croisée te remercieront, à leur façon. Prends ces épaulières.');
