INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredItemId1, RequiredItemCount1, RequiredItemId2, RequiredItemCount2, RequiredItemId3, RequiredItemCount3, RequiredItemId4, RequiredItemCount4) VALUES (910074, 2, -1, 0, 718, 960, 0, 1, -602, -2260, 'Les druides du Croc', 'Rapporte à Falla les gemmes de Cobrahn, d''Anacondra, de Pythas et de Serpentis.', 'Cobrahn, Anacondra, Pythas, Serpentis. Ils étaient les meilleurs élèves de Naralex. Ils portent chacun une gemme du rêve, volée à leur maître. Avec elles, ils changent les bêtes et tiennent le cauchemar ouvert. Arrache-leur ces gemmes. Tant qu''un seul les porte, le disciple ne pourra pas commencer.', 'Retourne voir Falla Vent-de-sagesse.', 910793, 1, 9738, 1, 9739, 1, 9740, 1, 9741, 1);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910074, 910070, 0);
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910074, 1, 1, 'Combien de traîtres respirent encore ?');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910074, 1, 'Les quatre gemmes… Elles sont tièdes, comme un cœur qui ralentit. Le cauchemar a perdu ses gardiens. Prends ces jambières. Le disciple t''attend en bas.');
