INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredNpcOrGo1, RequiredNpcOrGoCount1, RequiredItemId1, RequiredItemCount1) VALUES (910075, 2, -1, 0, 718, 960, 0, 1, -602, -2260, 'Le réveil de Naralex', 'Accompagne le Disciple de Naralex jusqu''au bassin, tue Mutanus le Dévoreur et porte l''Éclat luminescent à Falla.', 'Le disciple attend depuis des années. Les quatre traîtres doivent tomber avant qu''il commence. Il connaît le chant qui réveille Naralex, mais le cauchemar envoie ses bêtes chaque fois qu''il commence. Avec la Larme des lunes, Falla dit que son chant tiendra. Toi, tu tiendras les bêtes. Accompagne-le jusqu''au bassin de Naralex et protège-le. Ce qui viendra à la fin sera pire que les traîtres.', 'Retourne voir Falla Vent-de-sagesse.', 37711, 10, 3654, 1, 10441, 1);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910075, 910070, 0);
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910075, 1, 1, 'Naralex s''est-il réveillé ?');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910075, 1, 'Il s''est réveillé… et il s''est envolé avec son disciple, vers le nord. Le cauchemar ne s''est pas éteint, mais il a perdu son rêveur. Cet éclat vient de la bête qui le dévorait : il luit encore. Les Tarides vont pouvoir guérir.');
