INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RewardItem2, RewardAmount2, RequiredItemId1, RequiredItemCount1) VALUES (910076, 2, -1, 0, 17, 900, 10649, 1, -545, -2673, 'Une savane qui guérit', 'Porte l''Éclat de cauchemar à Tonga Totem-runique, à la Croisée.', 'J''ai purifié l''éclat autant que j''ai pu. Il en reste ceci : un morceau du cauchemar, qui ne fera plus de mal. Porte-le à Tonga. C''est à lui de dire à la Croisée, à Thork et à Kirge que les oasis vont revivre.', 'Retourne voir Tonga Totem-runique.', 910794, 1, 37711, 10, 10649, 1);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910076, 0, 1);
