INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910076, 1, 1, 'Falla m''a fait prévenir. Alors ?');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910076, 1, 'Naralex est libre. Les traîtres sont tombés. Les bassins ne se rempliront pas en un jour, mais l''eau sera de nouveau de l''eau. Grâce à toi, la savane respire. Les Tarides sont à toi, autant qu''à nous.');
