-- Faux indicateurs de quête des abords et des Cavernes (passe de la migration 120).
CREATE TABLE solazeroth_v3_t5_faux_indicateurs (entry INT UNSIGNED NOT NULL PRIMARY KEY) SELECT DISTINCT t.entry FROM creature c JOIN creature_template t ON t.entry = c.id WHERE ((c.map = 1 AND c.zoneId = 718) OR c.map = 43) AND (t.npcflag & 2) AND NOT EXISTS (SELECT 1 FROM creature_queststarter q WHERE q.id = t.entry AND NOT EXISTS (SELECT 1 FROM disables d WHERE d.sourceType = 1 AND d.entry = q.quest)) AND NOT EXISTS (SELECT 1 FROM creature_questender q WHERE q.id = t.entry AND NOT EXISTS (SELECT 1 FROM disables d WHERE d.sourceType = 1 AND d.entry = q.quest));
UPDATE creature_template t JOIN solazeroth_v3_t5_faux_indicateurs f ON f.entry = t.entry SET t.npcflag = t.npcflag & ~2;
